package mediagate
import("context";"net/http";"net/http/httptest";"net/url";"strings";"testing";"time")
type fakeQuota struct{q *Quota};func(f fakeQuota)GetQuota(context.Context,string)(*Quota,error){return f.q,nil}
type fakeCache struct{usage int64;ok bool;user string};func(f *fakeCache)GetUser(context.Context,string)(string,error){return f.user,nil};func(f *fakeCache)SetUser(context.Context,string,string,time.Duration)error{return nil};func(f *fakeCache)GetUsage(context.Context,string)(int64,bool,error){return f.usage,f.ok,nil};func(f *fakeCache)SetUsage(context.Context,string,int64,time.Duration)error{return nil};func(f *fakeCache)AddUsage(context.Context,string,int64)error{return nil}
type fakeResolver struct{};func(fakeResolver)WhoAmI(context.Context,string)(string,error){return "@alice:example.org",nil};func(fakeResolver)MediaBytesSince(context.Context,string,time.Time)(int64,error){return 90,nil}
func TestUploadOverFileLimitReturnsMatrixTooLarge(t *testing.T){target,_:=url.Parse("http://127.0.0.1:9");g:=New(target,fakeQuota{&Quota{MaxFileBytes:5}},&fakeCache{},fakeResolver{});r:=httptest.NewRequest(http.MethodPost,"/_matrix/media/v3/upload",strings.NewReader("123456"));r.Header.Set("Authorization","Bearer test");r.ContentLength=6;w:=httptest.NewRecorder();g.ServeHTTP(w,r);if w.Code!=413||!strings.Contains(w.Body.String(),"M_TOO_LARGE"){t.Fatalf("want M_TOO_LARGE, got %d: %s",w.Code,w.Body.String())}}
func TestUploadOverTotalLimitReturnsMatrixTooLarge(t *testing.T){target,_:=url.Parse("http://127.0.0.1:9");c:=&fakeCache{usage:90,ok:true};g:=New(target,fakeQuota{&Quota{MaxTotalBytes:100,MaxFileBytes:50,Period:"lifetime"}},c,fakeResolver{});r:=httptest.NewRequest(http.MethodPost,"/_matrix/media/v1/upload",strings.NewReader("12345678901"));r.Header.Set("Authorization","Bearer test");r.ContentLength=11;w:=httptest.NewRecorder();g.ServeHTTP(w,r);if w.Code!=413||!strings.Contains(w.Body.String(),"M_TOO_LARGE"){t.Fatalf("want total quota rejection, got %d: %s",w.Code,w.Body.String())}}
